'use strict';
// Data the new popup/settings UI reads from the upstream bundle instead of
// copying it by hand: the translation language list, language names for the
// three interface languages, and the icons of the twelve service templates.
// Output: ui/src/generated/*.json (regenerated by every build).
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const acorn=require('acorn'),walk=require('acorn-walk');
const {MAGPIE_ICON}=require('./patch-segment.cjs');

const root=path.resolve(__dirname,'..'),out=path.join(root,'ui','src','generated');
const TEMPLATES=['bing','google','deepl','deeplx','magpie','openai','claude','gemini','deepseek','openrouter','ollama','custom-ai'];

function literal(node){
 if(node.type==='Literal')return node.value;
 if(node.type==='TemplateLiteral'&&!node.expressions.length)return node.quasis[0].value.cooked;
 return undefined;
}
function keyOf(p){return p.key?.name??p.key?.value;}
function objects(source){
 const ast=acorn.parse(source,{ecmaVersion:'latest',sourceType:'module'}),list=[];
 walk.simple(ast,{ObjectExpression(n){list.push(n);},ArrayExpression(n){list.push(n);}});
 return list;
}
function plain(node){
 const o={};
 for(const p of node.properties){if(p.type!=='Property')continue;const v=literal(p.value);if(typeof v==='string')o[keyOf(p)]=v;}
 return o;
}

function build(){
 const popup=fs.readFileSync(path.join(root,'upstream','popup.js'),'utf8');
 const nodes=objects(popup);

 // Language list: [["auto","auto"],["zh-CN","Simplified Chinese"],...]
 const list=nodes.find(n=>n.type==='ArrayExpression'&&n.elements.length>100&&n.elements.every(e=>e?.type==='ArrayExpression'&&e.elements.length===2&&typeof literal(e.elements[0])==='string')&&literal(n.elements[0].elements[0])==='auto');
 assert.ok(list,'upstream language list');
 const codes=[...new Set(list.elements.map(e=>literal(e.elements[0])).filter(c=>c!=='auto'))];

 // Per-interface-language name tables: the one naming English 英语 / 英語 / English.
 const tables=nodes.filter(n=>n.type==='ObjectExpression'&&n.properties.length>100&&n.properties.some(p=>keyOf(p)==='zh-CN-NE')).map(plain);
 const pick=en=>{const t=tables.find(t=>t.en===en);assert.ok(t,'language names '+en);return t;};
 const names={'zh-CN':pick('英语'),'zh-TW':pick('英語'),en:pick('English')};
 for(const lang of Object.keys(names)){
  const t={};for(const c of [...codes,'auto'])if(names[lang][c])t[c]=names[lang][c];
  names[lang]=t;
 }

 // Service icons: the map whose entries are data URLs keyed by service id.
 const options=fs.readFileSync(path.join(root,'upstream','options.js'),'utf8');
 const iconMap=objects(options).find(n=>n.type==='ObjectExpression'&&n.properties.some(p=>keyOf(p)==='openai'&&String(literal(p.value)).startsWith('data:image/'))&&n.properties.some(p=>keyOf(p)==='deeplx'));
 assert.ok(iconMap,'upstream service icon map');
 const all=plain(iconMap),icons={};
 for(const id of TEMPLATES){
  const icon=id==='magpie'?MAGPIE_ICON:all[id];
  assert.ok(icon?.startsWith('data:image/'),'icon '+id);
  icons[id]=icon;
 }

 fs.mkdirSync(out,{recursive:true});
 fs.writeFileSync(path.join(out,'languages.json'),JSON.stringify({codes,names})+'\n');
 fs.writeFileSync(path.join(out,'service-icons.json'),JSON.stringify(icons)+'\n');
 return {languages:codes.length,icons:Object.keys(icons).length};
}

module.exports={build,TEMPLATES};
if(require.main===module)console.log(build());
